@@ -1563,12 +1595,46 @@ static int pxa2xx_spi_resume(struct device *dev)
 	int status;
 
 	/* Enable the SSP clock */
-	if (!pm_runtime_suspended(dev)) {
-		status = pxa2xx_spi_clk_enable(drv_data);
-		if (status)
-			return status;
+	status = pxa2xx_spi_clk_enable(drv_data);
+	if (status)
+		goto out_put;
