- 	case AMD_VSDB_PANEL_TYPE_OLED:
- 		link->panel_type = PANEL_TYPE_OLED;
- 		break;
- 	case AMD_VSDB_PANEL_TYPE_MINILED:
- 		link->panel_type = PANEL_TYPE_MINILED;
